const first = $input.first().json;
const raw =
  first.output ??
  first.text ??
  first.response?.generations?.[0]?.[0]?.text ??
  '';

if (!raw) {
  throw new Error('No model text found. Keys seen: ' + Object.keys(first).join(', '));
}

const clean = String(raw).replace(/```json|```/g, '').trim();
const parsed = JSON.parse(clean);

if (!Array.isArray(parsed.diagnoses)) {
  throw new Error('Reply has no "diagnoses" array: ' + clean.slice(0, 200));
}

return parsed.diagnoses.map(d => ({ json: d }));

const note = $('Edit Fields').first().json.note;
const diagnoses = $('Extract').all().map(i => i.json);
const rows = $input.all().map(i => i.json);

const UNCERTAIN = /\b(possible|possibly|probable|probably|suspected|suspect|questionable|rule out|r\/o|likely|consistent with|compatible with|working diagnosis)\b/i;

return diagnoses.map(d => {
  const cats = rows
    .filter(r => r.search_term === d.search_term)
    .map(r => ({ category: r.category, title: r.category_title, n: r.matching_codes }));

  return {
    json: {
      search_term: d.search_term,
      evidence: d.evidence,
      evidence_exact: note.includes(d.evidence),
      uncertain: UNCERTAIN.test(d.evidence) || UNCERTAIN.test(d.search_term),
      note,
      category_count: cats.length,
      categories_text: cats
        .map(c => `${c.category} | ${c.title} | ${c.n} matching codes`)
        .join('\n')
    }
  };
});

