const bundles = $('Bundle categories').all().map(i => i.json);
const picks = $input.all().map(i => i.json);

return picks.map((p, idx) => {
  const b = bundles[idx];
  const flags = [];

  let parsed = null;
  try {
    const raw = String(p.output ?? '').replace(/```json|```/g, '').trim();
    parsed = JSON.parse(raw);
  } catch (e) {
    flags.push('reply_not_valid_json');
  }

  const valid = new Set(
    b.categories_text
      .split('\n')
      .filter(l => l.includes(' | '))
      .map(l => l.split(' | ')[0].trim())
  );

  const category = parsed?.category ?? null;
  if (parsed && category === null) flags.push('no_category_selected');
  if (category !== null && !valid.has(category)) flags.push('category_not_in_list');
  if (!b.evidence_exact) flags.push('evidence_not_exact_quote');
  if (b.uncertain) flags.push('uncertain_diagnosis_check_setting');
  if (b.category_count === 0) flags.push('no_categories_found');

  const usable = category !== null && valid.has(category) && !b.uncertain;

  return {
    json: {
      search_term: b.search_term,
      evidence: b.evidence,
      category: usable ? category : '',
      category_reason: parsed?.reason ?? null,
      flags: flags.join(', ')
    }
  };
});

const catBundles = $('Bundle categories').all().map(i => i.json);
const checks = $('Check category').all().map(i => i.json);
const rows = $input.all().map(i => i.json);

return checks.map((c, idx) => {
  const b = catBundles[idx];
  const codes = c.category
    ? rows.filter(r => r.category === c.category)
    : [];
  const total = codes.length ? Number(codes[0].total_in_category) : 0;

  return {
    json: {
      search_term: c.search_term,
      evidence: c.evidence,
      evidence_exact: b.evidence_exact,
      uncertain: b.uncertain,
      note: b.note,
      category: c.category,
      category_flags: c.flags,
      code_count: codes.length,
      total_in_category: total,
      codes_truncated: total > codes.length,
      codes_text: codes.map(r => `${r.code} | ${r.long_desc}`).join('\n')
    }
  };
});

