=You are assigning an ICD-10-CM diagnosis code.

Rules:
- Choose exactly ONE code, and it must appear in the CODES list below. Never use a code from memory.
- Choose the most specific code that the DIAGNOSIS, EVIDENCE and PATIENT NOTE support. Do not assume any detail the note does not state (such as a complication, a body side, or a cause).
- If the CODES list is empty, or no code is supported by the documentation, set code to null.
- Return ONLY valid JSON, no other text, in this shape:
{"code":"...","reason":"one short sentence"}

DIAGNOSIS: {{ $json.search_term }}

EVIDENCE: {{ $json.evidence }}

PATIENT NOTE: {{ $json.note }}

CATEGORY: {{ $json.category }}

CODES (code | description):
{{ $json.codes_text }}

parameters.jsCode:
const bundles = $('Bundle codes').all().map(i => i.json);
const picks = $input.all().map(i => i.json);

const normalize = c => String(c).replace(/[.\s]/g, '').toUpperCase();

return picks.map((p, idx) => {
  const b = bundles[idx];
  const flags = new Set(
    String(b.category_flags || '').split(',').map(s => s.trim()).filter(Boolean)
  );

  let parsed = null;
  try {
    const raw = String(p.output ?? '').replace(/```json|```/g, '').trim();
    parsed = JSON.parse(raw);
  } catch (e) {
    flags.add('reply_not_valid_json');
  }

  const codes = new Map(
    String(b.codes_text || '')
      .split('\n')
      .filter(l => l.includes(' | '))
      .map(l => {
        const [code, ...rest] = l.split(' | ');
        return [code.trim(), rest.join(' | ').trim()];
      })
  );

  const modelCode = parsed?.code ?? null;
  const normalized = modelCode !== null ? normalize(modelCode) : null;
  const inList = normalized !== null && codes.has(normalized);

  if (parsed && modelCode === null) flags.add('no_code_selected');
  if (modelCode !== null && !inList) flags.add('code_not_in_list');
  if (!b.evidence_exact) flags.add('evidence_not_exact_quote');
  if (b.uncertain) flags.add('uncertain_diagnosis_check_setting');
  if (b.codes_truncated) flags.add('codes_truncated');

  const finalCode = inList && !b.uncertain ? normalized : null;

  return {
    json: {
      diagnosis: b.search_term,
      evidence: b.evidence,
      model_code: modelCode,
      final_code: finalCode,
      description: finalCode ? codes.get(finalCode) : null,
      reason: parsed?.reason ?? null,
      status: finalCode && flags.size === 0 ? 'OK' : 'REVIEW',
      flags: [...flags].join(', ')
    }
  };
});
